
'use strict';
const KEY='fadak-accounting-standalone-v3';
const menu=[['dashboard','نمای کلی','▦'],['products','کالاها و قیمت‌ها','◈'],['stores','فروشگاه‌ها','⌂'],['deliveries','تحویل امانی','⇧'],['sales','ثبت فروش','＋'],['pos','کارت‌خوان','▣'],['reconcile','بستن ماه','✓'],['reports','گزارش‌ها','▤'],['settings','تنظیمات و پشتیبان','⚙']];
const productSeed=[{id:'p1',name:'روغن زیتون ۴ لیتری',grade:1,unit:'گالن',prod:780000,price:980000,active:true},{id:'p2',name:'کنسرو زیتون ۷۰۰ گرمی',grade:1,unit:'عدد',prod:145000,price:195000,active:true},{id:'p3',name:'وکیوم زیتون ۱۴۰۰ گرمی',grade:2,unit:'بسته',prod:220000,price:295000,active:true}];
const isoToday=()=>{const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')};
function seed(){
const d=isoToday();
if(window.FADAK_DEMO===true){
return {
version:4,mode:'demo',products:structuredClone(productSeed),
stores:[
{id:'s1',name:'فروشگاه نمونه مرکزی',manager:'مسئول نمونه',phone:'',active:true},
{id:'s2',name:'فروشگاه نمونه بازار',manager:'مسئول نمونه',phone:'',active:true}
],
deliveries:[{id:'d-demo',date:d,storeId:'s1',productId:'p1',qty:70,doc:'DEMO-001',note:'داده‌ی ساختگی برای نمایش'}],
sales:[{id:'sale-demo',date:d,invoice:'DEMO-1001',storeId:'s1',items:[{productId:'p1',qty:43,price:980000}],total:42140000,method:'card',cardAmount:42140000,cashAmount:0,reference:'DEMO-TRACE-1001',note:'تراکنش ساختگی؛ گزارش واقعی نیست'}],
pos:[{id:'pos-demo',date:d,amount:42140000,reference:'DEMO-TRACE-1001',terminal:'DEMO-POS',storeId:'s1',note:'تراکنش آزمایشی؛ واقعی نیست'}],
adjustments:[],closings:[],
settings:{businessName:'زیتون فدک',currency:'تومان',apiBase:''}
};
}
return {version:4,mode:'live',products:[],stores:[],deliveries:[],sales:[],pos:[],adjustments:[],closings:[],settings:{businessName:'زیتون فدک',currency:'تومان',apiBase:''}}
}
function fresh(){return JSON.parse(JSON.stringify(seed()))}
function validDb(x){if(window.FADAK_DEMO===true){if(!x||x.mode!=='demo')return false}else if(x&&x.mode==='demo')return false;const keys=['products','stores','deliveries','sales','pos','adjustments','closings'];if(!x||!keys.every(k=>Array.isArray(x[k])))return false;const idKeys=['products','stores','deliveries','sales','pos','adjustments'];return idKeys.every(k=>x[k].every(r=>r&&/^[A-Za-z0-9_-]{1,100}$/.test(String(r.id??''))))}
function load(){try{const x=JSON.parse(localStorage.getItem(KEY)||'null');if(validDb(x))return x}catch(e){}return fresh()}
let db=load(),page='dashboard',theme=localStorage.getItem(KEY+'-theme')||'light',reportMonth=isoToday().slice(0,7),reportStore='all',countStore='s1';
document.documentElement.dataset.theme=theme;
const $=id=>document.getElementById(id);const num=n=>Number.isFinite(Number(n))?Number(n):0;const uid=prefix=>prefix+'-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,7);
const fa=n=>new Intl.NumberFormat('fa-IR',{maximumFractionDigits:2}).format(num(n));const money=n=>fa(Math.round(num(n)))+' تومان';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function notify(msg){const t=$('toast');t.textContent=msg;t.classList.remove('hidden');clearTimeout(window.__toastTimer);window.__toastTimer=setTimeout(()=>t.classList.add('hidden'),3100)}
function save(){try{localStorage.setItem(KEY,JSON.stringify(db));if(window.FADAK_DEMO!==true&&sessionStorage.getItem(KEY+'-sync')==='1')queueServerSync();return true}catch(e){notify('ذخیره مرورگر انجام نشد؛ فوراً نسخه پشتیبان بگیر.');return false}}
function product(id){return db.products.find(p=>p.id===id)}function store(id){return db.stores.find(s=>s.id===id)}
function todayPersian(d){try{return new Intl.DateTimeFormat('fa-IR-u-ca-persian',{year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(d+'T12:00:00'))}catch(e){return d}}
function monthPersian(m){try{return new Intl.DateTimeFormat('fa-IR-u-ca-persian',{year:'numeric',month:'long'}).format(new Date(m+'-15T12:00:00'))}catch(e){return m}}
function monthBounds(m){const [y,mo]=m.split('-').map(Number);const next=new Date(y,mo,1);return {start:m+'-01',end:next.getFullYear()+'-'+String(next.getMonth()+1).padStart(2,'0')+'-01'}}
function nav(){const html=menu.map(n=>`<button class="${page===n[0]?'active':''}" onclick="go('${n[0]}')"><span class="icon">${n[2]}</span><span>${n[1]}</span>${page===n[0]?'<i class="dot"></i>':''}</button>`).join('');$('sideNav').innerHTML=html;$('mobileNav').innerHTML=menu.map(n=>`<button class="${page===n[0]?'active':''}" onclick="go('${n[0]}')"><span>${n[2]}</span>${n[1]}</button>`).join('');$('crumbTitle').textContent=menu.find(n=>n[0]===page)?.[1]||'نمای کلی'}
function go(p){page=p;nav();render()}
function sum(arr,fn){return arr.reduce((a,x)=>a+fn(x),0)}
function delivered(pid,sid,until=null){return sum(db.deliveries.filter(d=>d.productId===pid&&(!sid||d.storeId===sid)&&(!until||d.date<until)),d=>num(d.qty))}
function soldQty(pid,sid,from=null,until=null){return sum(db.sales.filter(s=>(!sid||s.storeId===sid)&&(!from||s.date>=from)&&(!until||s.date<until)),s=>sum(s.items.filter(i=>i.productId===pid),i=>num(i.qty)))}
function adjustments(pid,sid,from=null,until=null){return sum(db.adjustments.filter(a=>a.productId===pid&&(!sid||a.storeId===sid)&&(!from||a.date>=from)&&(!until||a.date<until)),a=>num(a.qty))}
function stock(pid,sid,until=null){return delivered(pid,sid,until)-soldQty(pid,sid,null,until)+adjustments(pid,sid,null,until)}
function saleTotal(s){return num(s.total??sum(s.items||[],i=>num(i.qty)*num(i.price)))}
function salesAmount(from=null,until=null,sid=null){return sum(db.sales.filter(s=>(!from||s.date>=from)&&(!until||s.date<until)&&(!sid||s.storeId===sid)),saleTotal)}
function cardFromSales(from=null,until=null,sid=null){return sum(db.sales.filter(s=>(!from||s.date>=from)&&(!until||s.date<until)&&(!sid||s.storeId===sid)),s=>num(s.cardAmount))}
function posAmount(from=null,until=null,sid=null){return sum(db.pos.filter(t=>(!from||t.date>=from)&&(!until||t.date<until)&&(!sid||t.storeId===sid)),t=>num(t.amount))}
function productOptions(sel=''){return db.products.filter(p=>p.active!==false).map(p=>`<option value="${esc(p.id)}" ${p.id===sel?'selected':''}>${esc(p.name)} · درجه ${fa(p.grade)}</option>`).join('')}
function storeOptions(sel=''){return db.stores.filter(s=>s.active!==false).map(s=>`<option value="${esc(s.id)}" ${s.id===sel?'selected':''}>${esc(s.name)}</option>`).join('')}
function panelHead(title,sub=''){return `<div class="panel-head"><div><h3>${title}</h3>${sub?`<p>${sub}</p>`:''}</div></div>`}
function kpi(label,value,icon,foot,cl=''){return `<article class="kpi ${cl}"><div class="kpi-top"><span>${label}</span><i>${icon}</i></div><strong>${value}</strong><div class="kpi-foot">${foot}</div></article>`}
function tableEmpty(colspan,msg='هنوز اطلاعاتی ثبت نشده است.'){return `<tr><td class="empty" colspan="${colspan}">${msg}</td></tr>`}
function demoNotice(){return `<div class="notice warn"><b>حالت نمایشی:</b> بخشی از اطلاعات برای آزمایش سیستم ساخته شده‌اند و گزارش واقعی فروش یا بانک نیستند. قبل از استفاده واقعی، داده‌های نمونه را پاک یا با اطلاعات معتبر جایگزین کن.</div>`}
function dashboard(){const month=reportMonth,b=monthBounds(month),salesM=salesAmount(b.start,b.end),cardM=cardFromSales(b.start,b.end),posM=posAmount(b.start,b.end),gap=cardM-posM;const deliveredAll=sum(db.deliveries,d=>num(d.qty)),soldAll=sum(db.sales,s=>sum(s.items,i=>num(i.qty)));const last=[...db.sales].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,5);return `<section class="hero"><div class="hero-copy"><div class="eyebrow"><span>✦</span> پنل هوشمند حسابداری امانی</div><h1>حساب‌وکتاب،<br><em>روشن‌تر از همیشه.</em></h1><p>تحویل، فروش و تسویه فروشگاه‌ها را در یک نمای ساده و قابل پیگیری ببین.</p><div class="hero-actions"><button class="btn light" onclick="go('deliveries')">＋ ثبت تحویل جدید</button><button class="btn ghost-light" onclick="go('reconcile')">مشاهده گزارش ماهانه ↗</button></div></div><div class="hero-art scene" aria-hidden="true"><div class="stage"><div class="floor"></div><div class="ring"><div class="spin"><div class="slot" style="--a:0.0deg;--s:1"><div class="cnt"><i class="bead"></i></div></div><div class="slot" style="--a:51.43deg;--s:0.75"><div class="cnt"><i class="bead"></i></div></div><div class="slot" style="--a:102.86deg;--s:0.9"><div class="cnt"><i class="bead"></i></div></div><div class="slot" style="--a:154.29deg;--s:0.65"><div class="cnt"><i class="bead"></i></div></div><div class="slot" style="--a:205.71deg;--s:1.05"><div class="cnt"><i class="bead"></i></div></div><div class="slot" style="--a:257.14deg;--s:0.8"><div class="cnt"><i class="bead"></i></div></div><div class="slot" style="--a:308.57deg;--s:0.7"><div class="cnt"><i class="bead"></i></div></div></div></div><div class="big"><i class="stem"></i><i class="leaf"></i><i class="leaf l2"></i><i class="fruit f1"></i><i class="fruit f2"></i><i class="fruit f3"></i></div></div><div class="glass-chip chip-a">↗ <small>گردش کالا</small></div><div class="glass-chip chip-b">✓ <small>حساب قابل بررسی</small></div></div></section>${demoNotice()}<div class="section-head"><div><span class="kicker">نمای لحظه‌ای</span><h2>سلام! اینجا چه خبره؟</h2><p>خلاصه‌ای از اطلاعات ثبت‌شده در سامانه</p></div><button class="btn soft" onclick="go('reports')">مشاهده همه گزارش‌ها ↗</button></div><div class="kpis">${kpi('فروش ثبت‌شده در ماه',money(salesM),'↗','طبق فاکتورهای ثبت‌شده','highlight')}${kpi('کالاهای تحویلی',fa(deliveredAll)+' واحد','⇧','مجموع رسیدهای ثبت‌شده')}${kpi('کالاهای فروخته‌شده',fa(soldAll)+' واحد','▤','بر اساس ریز فاکتورها')}${kpi('اختلاف جمع کارت‌خوان',money(Math.abs(gap)),'⇄',Math.abs(gap)<1?'جمع‌ها برابرند':'نیازمند بررسی مستقل',Math.abs(gap)<1?'':'alert')}</div><div class="cols"><section class="panel">${panelHead('آخرین فروش‌ها','فاکتورهای ثبت‌شده در سامانه')}<div class="table-wrap"><table class="data-table"><thead><tr><th>تاریخ</th><th>شماره فاکتور</th><th>فروشگاه</th><th>کالاها</th><th>جمع فاکتور</th><th>پرداخت کارت</th></tr></thead><tbody>${last.map(s=>`<tr><td>${esc(todayPersian(s.date))}</td><td><b>${esc(s.invoice||'—')}</b></td><td>${esc(store(s.storeId)?.name||'فروشگاه حذف‌شده')}</td><td>${esc(s.items.map(i=>(product(i.productId)?.name||'کالای حذف‌شده')+' × '+fa(i.qty)).join('، '))}</td><td>${money(saleTotal(s))}</td><td>${money(s.cardAmount)}</td></tr>`).join('')||tableEmpty(6)}</tbody></table></div><div class="form-actions"><button class="btn soft" onclick="go('sales')">＋ ثبت فروش جدید</button><button class="btn soft" onclick="go('pos')">بررسی کارت‌خوان</button></div></section><section class="panel stock-panel">${panelHead('موجودی مورد انتظار','بر اساس تحویل‌ها و فروش‌های ثبت‌شده')}${db.products.filter(p=>p.active!==false).slice(0,6).map((p,i)=>{const d=delivered(p.id),sold=soldQty(p.id),rem=d-sold+adjustments(p.id);const pct=d>0?Math.min(100,Math.max(0,rem/d*100)):0;return `<div class="stock-item"><div class="stock-icon">${['◉','◇','◍'][i%3]}</div><div class="stock-info"><div class="stock-info-top"><b>${esc(p.name)}</b><span>${fa(rem)} / ${fa(d)}</span></div><div class="bar"><span style="width:${pct}%"></span></div></div></div>`}).join('')||'<p class="muted">ابتدا محصول تعریف کن.</p>'}<div class="form-actions"><button class="btn soft" onclick="go('reconcile')">شمارش پایان ماه</button></div></section></div>`}
function productsPage(){return `<div class="section-head"><div><span class="kicker">کاتالوگ</span><h2>کالاها و قیمت‌ها</h2><p>تغییر قیمت جدید روی فاکتورهای قبلی اثر نمی‌گذارد.</p></div><span class="badge">${fa(db.products.length)} محصول</span></div><div class="panel">${panelHead('افزودن محصول جدید','اطلاعات محصول را وارد کن') }<form id="productForm"><div class="form-grid"><label class="field"><span>نام محصول</span><input name="name" required placeholder="مثلاً روغن زیتون ۳ لیتری"></label><label class="field"><span>درجه محصول</span><select name="grade"><option value="1">درجه ۱</option><option value="2">درجه ۲</option><option value="3">درجه ۳</option></select></label><label class="field"><span>واحد شمارش</span><select name="unit"><option>عدد</option><option>گالن</option><option>بطری</option><option>بسته</option><option>کیلوگرم</option><option>قوطی</option></select></label><label class="field"><span>قیمت تولید / تسویه (تومان)</span><input name="prod" type="number" min="0" step="1" value="0" required></label><label class="field"><span>قیمت مصرف‌کننده (تومان)</span><input name="price" type="number" min="0" step="1" value="0" required></label></div><div class="form-actions"><button class="btn" type="submit">＋ افزودن محصول</button></div></form></div><div class="panel">${panelHead('فهرست محصولات','برای شروع قیمت‌ها را با اطلاعات واقعی کسب‌وکار تطبیق بده')}<div class="table-wrap"><table class="data-table"><thead><tr><th>نام محصول</th><th>درجه</th><th>واحد</th><th>قیمت تولید/تسویه</th><th>قیمت مصرف‌کننده</th><th>موجودی دفتری</th><th>عملیات</th></tr></thead><tbody>${db.products.map(p=>`<tr><td><input aria-label="نام محصول" class="form-control" style="min-width:175px" value="${esc(p.name)}" onchange="editProduct('${p.id}','name',this.value)"></td><td><select class="form-control" onchange="editProduct('${p.id}','grade',this.value)">${[1,2,3].map(g=>`<option value="${g}" ${g===num(p.grade)?'selected':''}>${fa(g)}</option>`).join('')}</select></td><td>${esc(p.unit||'عدد')}</td><td><input aria-label="قیمت تولید" class="form-control" type="number" min="0" style="min-width:115px" value="${num(p.prod)}" onchange="editProduct('${p.id}','prod',this.value)"></td><td><input aria-label="قیمت مصرف‌کننده" class="form-control" type="number" min="0" style="min-width:115px" value="${num(p.price)}" onchange="editProduct('${p.id}','price',this.value)"></td><td>${fa(stock(p.id))}</td><td><button class="btn small ${p.active===false?'soft':''}" onclick="toggleProduct('${p.id}')">${p.active===false?'فعال‌سازی':'غیرفعال‌کردن'}</button></td></tr>`).join('')||tableEmpty(7)}</tbody></table></div></div>`}
function storesPage(){return `<div class="section-head"><div><span class="kicker">شبکه فروش</span><h2>فروشگاه‌ها</h2><p>اطلاعات و گردش هر فروشگاه را جداگانه دنبال کن.</p></div></div><div class="panel">${panelHead('افزودن فروشگاه جدید')}<form id="storeForm"><div class="form-grid"><label class="field"><span>نام فروشگاه</span><input name="name" required placeholder="نام فروشگاه"></label><label class="field"><span>نام مسئول</span><input name="manager" placeholder="اختیاری"></label><label class="field"><span>شماره تماس (اختیاری)</span><input name="phone" type="tel" placeholder="شماره تماس"></label><label class="field"><span>وضعیت</span><select name="active"><option value="true">فعال</option><option value="false">غیرفعال</option></select></label></div><div class="form-actions"><button class="btn">＋ افزودن فروشگاه</button></div></form></div><div class="store-grid">${db.stores.map(s=>`<article class="store-card"><div class="store-card-head"><div class="store-avatar">⌂</div><div style="flex:1"><h3>${esc(s.name)}</h3><p>${esc(s.manager||'مسئول ثبت نشده')}${s.phone?' · '+esc(s.phone):''}</p><span class="badge ${s.active===false?'warn':'ok'}">${s.active===false?'غیرفعال':'فعال'}</span></div></div><div class="store-stats"><div><small>فروش ثبت‌شده</small><b>${money(salesAmount(null,null,s.id))}</b></div><div><small>موجودی مورد انتظار</small><b>${fa(db.products.reduce((n,p)=>n+stock(p.id,s.id),0))} واحد</b></div></div><div class="form-actions"><button class="btn small soft" onclick="showStoreReport('${s.id}')">گزارش این فروشگاه</button><button class="btn small soft" onclick="toggleStore('${s.id}')">${s.active===false?'فعال‌کردن':'غیرفعال‌کردن'}</button></div></article>`).join('')||'<div class="panel muted">هنوز فروشگاهی ثبت نشده است.</div>'}</div>`}
function deliveryPage(){return `<div class="section-head"><div><span class="kicker">ثبت حواله</span><h2>تحویل و اصلاح موجودی</h2><p>محموله‌های امانی را ثبت کن؛ موجودی اولیه یا اختلاف شمارش را با دلیل مستند اصلاح کن.</p></div></div><div class="panel">${panelHead('ثبت موجودی اولیه یا اصلاح','مثبت برای افزودن، منفی برای کسری یا ضایعات؛ دلیل را دقیق ثبت کن')}<form id="adjustmentForm"><div class="form-grid"><label class="field"><span>فروشگاه</span><select name="storeId" required>${storeOptions()}</select></label><label class="field"><span>محصول</span><select name="productId" required>${productOptions()}</select></label><label class="field"><span>تغییر تعداد (+ / −)</span><input name="qty" type="number" step="0.01" required placeholder="مثلاً ۳۰ یا ۳-"></label><label class="field"><span>تاریخ</span><input name="date" type="date" value="${isoToday()}" required></label><label class="field"><span>علت</span><select name="reason"><option>ثبت موجودی اولیه</option><option>برگشت از مشتری</option><option>برگشت به مزرعه</option><option>ضایعات / خرابی</option><option>اصلاح پس از شمارش</option></select></label><label class="field"><span>شرح و مستند</span><input name="note" required placeholder="مثلاً صورت‌جلسه شمارش ۱۴۰۵/۰۷/۲۰"></label></div><div class="form-actions"><button class="btn" ${!db.stores.length?'disabled':''}>ثبت اصلاح موجودی</button></div></form><div class="notice warn">اصلاحات روی موجودی مورد انتظار اثر می‌گذارند اما سوابق قبلی فروش و تحویل را بازنویسی نمی‌کنند.</div></div>${!db.stores.length?'<div class="notice warn">برای شروع، ابتدا یک فروشگاه ثبت کن.</div>':''}<div class="panel">${panelHead('ثبت تحویل جدید','تعداد تحویل‌داده‌شده باید مطابق حواله واقعی باشد')}<form id="deliveryForm"><div class="form-grid"><label class="field"><span>فروشگاه دریافت‌کننده</span><select name="storeId" required>${storeOptions()}</select></label><label class="field"><span>محصول و درجه</span><select name="productId" required>${productOptions()}</select></label><label class="field"><span>تعداد تحویلی</span><input name="qty" type="number" min="0.01" step="0.01" required placeholder="مثلاً ۷۰"></label><label class="field"><span>تاریخ تحویل</span><input name="date" type="date" value="${isoToday()}" required></label><label class="field"><span>شماره حواله</span><input name="doc" placeholder="مثلاً F-1405-001"></label><label class="field"><span>یادداشت</span><input name="note" placeholder="اختیاری"></label></div><div class="form-actions"><button class="btn" ${!db.stores.length?'disabled':''}>✓ ثبت تحویل</button></div></form></div><div class="panel">${panelHead('تاریخچه تحویل‌ها','رسیدها و تعداد تحویل‌شده')}<div class="table-wrap"><table class="data-table"><thead><tr><th>تاریخ</th><th>فروشگاه</th><th>محصول</th><th>تعداد</th><th>حواله</th><th>یادداشت</th></tr></thead><tbody>${[...db.deliveries].sort((a,b)=>b.date.localeCompare(a.date)).map(d=>`<tr><td>${esc(todayPersian(d.date))}</td><td>${esc(store(d.storeId)?.name||'—')}</td><td>${esc(product(d.productId)?.name||'—')} · درجه ${fa(product(d.productId)?.grade||0)}</td><td><b>${fa(d.qty)}</b></td><td>${esc(d.doc||'—')}</td><td>${esc(d.note||'—')}</td></tr>`).join('')||tableEmpty(6)}</tbody></table></div><p class="muted" style="font-size:10px">برای جلوگیری از تغییر بی‌سابقه حساب، رسید ثبت‌شده را حذف نکن؛ اصلاحات باید مستند باشند.</p></div><div class="panel">${panelHead('سابقه اصلاحات موجودی','ثبت موجودی اولیه، ضایعات، برگشتی‌ها و اصلاح پس از شمارش')}<div class="table-wrap"><table class="data-table"><thead><tr><th>تاریخ</th><th>فروشگاه</th><th>محصول</th><th>تغییر تعداد</th><th>علت</th><th>شرح</th></tr></thead><tbody>${[...db.adjustments].sort((a,b)=>b.date.localeCompare(a.date)).map(a=>`<tr><td>${esc(todayPersian(a.date))}</td><td>${esc(store(a.storeId)?.name||'—')}</td><td>${esc(product(a.productId)?.name||'—')}</td><td class="${num(a.qty)<0?'red-text':'green-text'}">${num(a.qty)>0?'+':''}${fa(a.qty)}</td><td>${esc(a.reason)}</td><td>${esc(a.note)}</td></tr>`).join('')||tableEmpty(6)}</tbody></table></div></div>`}
function saleLine(i,first=false){return `<div class="sale-line"><div class="sale-line-top"><span>ردیف ${fa(i+1)}</span><button class="btn small danger ${first?'hidden':''}" type="button" onclick="removeSaleLine(this)">حذف ردیف</button></div><div class="sale-line-grid"><label>محصول<select name="productId" required onchange="saleProductChanged(this)">${productOptions()}</select></label><label>تعداد<input name="qty" type="number" min="0.01" step="0.01" value="1" required oninput="updateSaleTotal()"></label><label>قیمت واحد (تومان)<input name="price" type="number" min="0" step="1" value="${num(db.products.find(p=>p.active!==false)?.price)}" required oninput="updateSaleTotal()"></label></div><div class="line-total">جمع این ردیف: <span>۰ تومان</span></div></div>`}
function salesPage(){return `<div class="section-head"><div><span class="kicker">فاکتور روزانه</span><h2>ثبت فروش</h2><p>ابتدا ریز کالاها را ثبت کن، سپس روش پرداخت و شماره پیگیری را وارد کن.</p></div></div>${demoNotice()}${!db.stores.length?'<div class="notice warn">برای ثبت فروش، ابتدا یک فروشگاه اضافه کن.</div>':''}<form class="panel" id="saleForm"><div class="form-grid"><label class="field"><span>فروشگاه</span><select name="storeId" required>${storeOptions()}</select></label><label class="field"><span>تاریخ فروش</span><input name="date" type="date" value="${isoToday()}" required></label><label class="field"><span>شماره فاکتور (اختیاری)</span><input name="invoice" placeholder="مثلاً F-1405-001"></label></div><div class="panel-head"><div><h3>کالاهای این فاکتور</h3><p>می‌توانی چند محصول به یک فاکتور اضافه کنی.</p></div><button class="btn small soft" type="button" onclick="addSaleLine()">＋ افزودن کالا</button></div><div id="saleLines">${saleLine(0,true)}</div><div class="total-strip"><span>جمع کل فاکتور</span><strong id="saleTotal">۰ تومان</strong></div><div class="form-grid"><label class="field"><span>روش پرداخت</span><select name="method" id="payMethod" onchange="togglePayment()"><option value="card">کارت‌خوان</option><option value="cash">نقدی</option><option value="mixed">ترکیبی (کارت + نقد)</option><option value="other">واریز یا روش دیگر</option></select></label><label class="field" id="cardField"><span>مبلغی که کارت‌خوان کشیده (تومان)</span><input name="cardAmount" id="cardAmount" type="number" min="0" step="1" value="0" oninput="updatePaymentHint()" required></label><label class="field"><span>شماره مرجع / پیگیری</span><input name="reference" placeholder="از رسید کارت‌خوان"></label><label class="field"><span>یادداشت</span><input name="note" placeholder="اختیاری"></label></div><div id="paymentHint" class="notice">برای پرداخت کارت‌خوان، شماره مرجع رسید را ثبت کن تا حساب‌دار بتواند تراکنش را مستقل تطبیق دهد.</div><div class="form-actions"><button class="btn" ${!db.stores.length||!db.products.some(p=>p.active!==false)?'disabled':''}>✓ ثبت فاکتور فروش</button><button type="reset" class="btn soft" onclick="setTimeout(()=>{updateSaleTotal();togglePayment()},0)">پاک‌کردن فرم</button></div></form><div class="panel">${panelHead('فاکتورهای ثبت‌شده','مبلغ روش پرداخت با گزارش مستقل کارت‌خوان یکی نیست')}<div class="table-wrap"><table class="data-table"><thead><tr><th>تاریخ</th><th>فاکتور</th><th>فروشگاه</th><th>محصولات</th><th>جمع کل</th><th>پرداخت کارت</th><th>مرجع</th></tr></thead><tbody>${[...db.sales].sort((a,b)=>b.date.localeCompare(a.date)).map(s=>`<tr><td>${esc(todayPersian(s.date))}</td><td>${esc(s.invoice||'—')}</td><td>${esc(store(s.storeId)?.name||'—')}</td><td>${esc(s.items.map(i=>(product(i.productId)?.name||'—')+' × '+fa(i.qty)).join('، '))}</td><td>${money(saleTotal(s))}</td><td>${money(s.cardAmount)}</td><td>${esc(s.reference||'ثبت نشده')}</td></tr>`).join('')||tableEmpty(7)}</tbody></table></div></div>`}
function posPage(){const m=reportMonth,b=monthBounds(m),cards=cardFromSales(b.start,b.end),actual=posAmount(b.start,b.end),gap=cards-actual;return `<div class="section-head"><div><span class="kicker">کنترل تراکنش</span><h2>کارت‌خوان و تطبیق پرداخت</h2><p>گزارش مستقل دستگاه را وارد کن تا با فاکتورهای ثبت‌شده مقایسه شود.</p></div></div><div class="notice warn"><b>اتصال واقعی فعال نیست.</b> این نسخه تراکنش را دستی یا از CSV وارد می‌کند. اتصال خودکار به دستگاه فقط با پشتیبانی و API رسمی شرکت پرداخت امکان‌پذیر است. اطلاعات نمونه با برچسب آزمایشی ثبت شده‌اند.</div><div class="kpis">${kpi('کارت‌خوان در فاکتورها',money(cards),'＋','بر اساس مبلغ ثبت‌شده هنگام فروش')}${kpi('گزارش مستقل واردشده',money(actual),'▣','تراکنش‌های واردشده برای ماه انتخابی')}${kpi('اختلاف دو جمع',money(Math.abs(gap)),'⇄',gap===0?'جمع‌ها برابرند':'نیازمند بررسی',gap===0?'':'alert')}${kpi('تعداد تراکنش‌های واقعی/نمونه',fa(db.pos.filter(t=>t.date>=b.start&&t.date<b.end).length),'#','در ماه انتخابی')}</div><div class="panel">${panelHead('ثبت دستی تراکنش','از گزارش کارت‌خوان یا رسید معتبر استفاده کن')}<form id="posForm"><div class="form-grid"><label class="field"><span>فروشگاه</span><select name="storeId">${storeOptions()}</select></label><label class="field"><span>تاریخ تراکنش</span><input name="date" type="date" value="${isoToday()}" required></label><label class="field"><span>مبلغ واقعی (تومان)</span><input name="amount" type="number" min="1" step="1" required></label><label class="field"><span>شماره مرجع / پیگیری</span><input name="reference" required placeholder="شماره درج‌شده روی رسید"></label><label class="field"><span>شماره پایانه (اختیاری)</span><input name="terminal" placeholder="شماره پایانه"></label><label class="field"><span>یادداشت</span><input name="note" placeholder="مثلاً ورود از گزارش روزانه"></label></div><div class="form-actions"><button class="btn" ${!db.stores.length?'disabled':''}>＋ ثبت تراکنش</button><button type="button" class="btn soft" onclick="$('csvInput').click()">⇧ واردکردن فایل CSV</button></div></form><div class="notice">قالب CSV پیشنهادی: <code>date,amount,reference,terminal,store</code>. برای مبلغ ریالی از ستون <code>amount_rial</code> استفاده کن. تراکنش مستقل نباید صرفاً از مبلغ فاکتور ساخته شود.</div></div><div class="panel">${panelHead('تراکنش‌های واردشده','تطبیق با فاکتور بر اساس شماره مرجع و مبلغ')}<div class="table-wrap"><table class="data-table"><thead><tr><th>تاریخ</th><th>فروشگاه</th><th>مبلغ واقعی</th><th>شماره مرجع</th><th>تطبیق</th><th>عملیات</th></tr></thead><tbody>${[...db.pos].sort((a,b)=>b.date.localeCompare(a.date)).map(t=>{const hits=db.sales.filter(s=>s.reference&&s.reference===t.reference&&s.storeId===t.storeId);const exact=hits.some(s=>Math.abs(num(s.cardAmount)-num(t.amount))<1);const label=!hits.length?'بدون فاکتور':exact?'مرجع و مبلغ برابر':'اختلاف مبلغ';return `<tr><td>${esc(todayPersian(t.date))}</td><td>${esc(store(t.storeId)?.name||'—')}</td><td>${money(t.amount)}</td><td>${esc(t.reference)}</td><td><span class="badge ${!hits.length?'warn':exact?'ok':'bad'}">${label}</span></td><td><button class="btn small danger" onclick="deletePOS('${t.id}')">حذف</button></td></tr>`}).join('')||tableEmpty(6)}</tbody></table></div><p class="muted" style="font-size:10px">فقط واردکردن گزارش معتبر یا آزمایشی مستقل باعث افزایش مبلغ گزارش واقعی می‌شود. شماره مرجع تکراری برای یک تاریخ پذیرفته نمی‌شود.</p></div>`}
function reconcilePage(){const b=monthBounds(reportMonth),sid=countStore||db.stores[0]?.id||'';const closing=db.closings.find(c=>c.month===reportMonth&&c.storeId===sid);const rows=db.products.filter(p=>p.active!==false).map(p=>{const opening=stock(p.id,sid,b.start);const received=delivered(p.id,sid,b.end)-delivered(p.id,sid,b.start);const sold=soldQty(p.id,sid,b.start,b.end);const adj=adjustments(p.id,sid,b.start,b.end);const expected=opening+received-sold+adj;const saved=closing?.counts?.find(x=>x.productId===p.id);return {p,opening,received,sold,adj,expected,actual:saved?saved.actual:null,variance:saved?num(saved.actual)-expected:null}});const mismatches=rows.filter(r=>r.variance!==null&&Math.abs(r.variance)>.0001).length;return `<div class="section-head"><div><span class="kicker">پایان دوره</span><h2>بستن ماه و شمارش موجودی</h2><p>عدد مورد انتظار را با شمارش واقعی فروشگاه مقایسه کن.</p></div><span class="badge">${esc(monthPersian(reportMonth))}</span></div><div class="panel"><div class="form-grid"><label class="field"><span>ماه گزارش</span><input id="reportMonth" type="month" value="${reportMonth}" onchange="reportMonth=this.value||reportMonth;render()"></label><label class="field"><span>فروشگاه</span><select id="countStore" onchange="countStore=this.value;render()">${storeOptions(sid)}</select></label></div><div class="metric-row"><div class="metric"><small>فروش ثبت‌شده ماه</small><b>${money(salesAmount(b.start,b.end,sid))}</b></div><div class="metric"><small>کارت‌خوان ثبت‌شده در فاکتورها</small><b>${money(cardFromSales(b.start,b.end,sid))}</b></div><div class="metric"><small>اختلاف موجودی ذخیره‌شده</small><b>${fa(mismatches)} محصول</b></div></div><div class="notice">فرمول ساده: موجودی اول ماه + تحویل ماه − فروش ماه + اصلاحات = موجودی مورد انتظار. اگر اختلاف دیدی، دلیلش را بررسی و ثبت کن؛ سیستم خودش درباره علت قضاوت نمی‌کند.</div><div class="table-wrap"><table class="data-table"><thead><tr><th>محصول</th><th>اول ماه</th><th>تحویل ماه</th><th>فروش ماه</th><th>اصلاحات</th><th>مورد انتظار</th><th>شمارش واقعی</th><th>اختلاف</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.p.name)} · درجه ${fa(r.p.grade)}</td><td>${fa(r.opening)}</td><td>${fa(r.received)}</td><td>${fa(r.sold)}</td><td>${fa(r.adj)}</td><td><b>${fa(r.expected)}</b></td><td><input aria-label="شمارش واقعی" class="form-control actual-count" data-product="${esc(r.p.id)}" type="number" min="0" step="0.01" style="min-width:95px" value="${r.actual===null?'':esc(r.actual)}" placeholder="تعداد"></td><td class="${r.variance===null?'muted':Math.abs(r.variance)>.0001?'red-text':'green-text'}">${r.variance===null?'ثبت نشده':fa(r.variance)}</td></tr>`).join('')||tableEmpty(8,'ابتدا محصول تعریف کن.')}</tbody></table></div><div class="form-actions"><button class="btn" onclick="saveClosing()">✓ ثبت شمارش ماه</button><button class="btn soft" onclick="downloadMonthCSV('${reportMonth}','${sid}')">دانلود گزارش CSV</button></div></div><div class="panel">${panelHead('بستن‌های قبلی','برای بازبینی سوابق ثبت‌شده')}<div class="table-wrap"><table class="data-table"><thead><tr><th>ماه</th><th>فروشگاه</th><th>تاریخ ثبت</th><th>محصولات دارای اختلاف</th><th>جمع فروش</th><th>کارت‌خوان واقعی</th></tr></thead><tbody>${[...db.closings].sort((a,b)=>b.month.localeCompare(a.month)).map(c=>`<tr><td>${esc(monthPersian(c.month))}</td><td>${esc(store(c.storeId)?.name||'—')}</td><td>${esc(todayPersian(c.closedAt))}</td><td>${fa(c.varianceCount)}</td><td>${money(c.salesTotal)}</td><td>${money(c.posTotal)}</td></tr>`).join('')||tableEmpty(6)}</tbody></table></div></div>`}
function reportsPage(){const b=monthBounds(reportMonth),sid=reportStore==='all'?null:reportStore;const prows=db.products.map(p=>{const qty=sum(db.sales.filter(s=>(!sid||s.storeId===sid)&&s.date>=b.start&&s.date<b.end),s=>sum(s.items.filter(i=>i.productId===p.id),i=>num(i.qty)));const amount=sum(db.sales.filter(s=>(!sid||s.storeId===sid)&&s.date>=b.start&&s.date<b.end),s=>sum(s.items.filter(i=>i.productId===p.id),i=>num(i.qty)*num(i.price)));return {p,qty,amount}});return `<div class="section-head"><div><span class="kicker">شفافیت مالی</span><h2>گزارش‌ها</h2><p>گزارش فروش و موجودی را برای ماه یا فروشگاه انتخابی آماده کن.</p></div><button class="btn" onclick="downloadMonthCSV('${reportMonth}',${sid?`'${sid}'`:'null'})">⇩ دانلود CSV</button></div><div class="panel"><div class="form-grid"><label class="field"><span>ماه گزارش</span><input type="month" value="${reportMonth}" onchange="reportMonth=this.value||reportMonth;render()"></label><label class="field"><span>فروشگاه</span><select onchange="reportStore=this.value;render()"><option value="all" ${reportStore==='all'?'selected':''}>همه فروشگاه‌ها</option>${storeOptions(reportStore)}</select></label></div><div class="metric-row"><div class="metric"><small>جمع فاکتورها</small><b>${money(salesAmount(b.start,b.end,sid))}</b></div><div class="metric"><small>جمع کارت در فاکتورها</small><b>${money(cardFromSales(b.start,b.end,sid))}</b></div><div class="metric"><small>جمع گزارش مستقل</small><b>${money(posAmount(b.start,b.end,sid))}</b></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>محصول</th><th>مقدار فروش</th><th>واحد</th><th>ارزش فروش</th><th>مانده مورد انتظار همه فروشگاه‌ها</th></tr></thead><tbody>${prows.map(r=>`<tr><td>${esc(r.p.name)} · درجه ${fa(r.p.grade)}</td><td>${fa(r.qty)}</td><td>${esc(r.p.unit||'عدد')}</td><td>${money(r.amount)}</td><td>${fa(sid?stock(r.p.id,sid):stock(r.p.id))}</td></tr>`).join('')||tableEmpty(5)}</tbody></table></div></div><div class="panel">${panelHead('خلاصه تطبیق کارت‌خوان','مقایسه جمع مبالغ مستقل برای بازه انتخابی')}<div class="match-card ${Math.abs(cardFromSales(b.start,b.end,sid)-posAmount(b.start,b.end,sid))<1?'good':'bad'}"><span class="match-icon">${Math.abs(cardFromSales(b.start,b.end,sid)-posAmount(b.start,b.end,sid))<1?'✓':'!'}</span><div><h3>${Math.abs(cardFromSales(b.start,b.end,sid)-posAmount(b.start,b.end,sid))<1?'جمع‌ها برابرند':'اختلاف نیازمند بررسی'}</h3><p>${money(Math.abs(cardFromSales(b.start,b.end,sid)-posAmount(b.start,b.end,sid)))}</p><small>این مقایسه جمع کل است؛ تطبیق دقیق هر پرداخت به شماره مرجع و تاریخ نیاز دارد.</small></div></div></div>`}
function settingsPage(){return `<div class="section-head"><div><span class="kicker">مدیریت سامانه</span><h2>تنظیمات و پشتیبان</h2><p>اطلاعات این نسخه در مرورگر همین دستگاه می‌ماند.</p></div></div>${demoNotice()}<div class="settings-grid"><article class="settings-card"><div class="settings-icon">⇩</div><h3>نسخه پشتیبان JSON</h3><p>محصولات، فروشگاه‌ها، تحویل‌ها، فروش‌ها و تراکنش‌های ذخیره‌شده را برای بازیابی دانلود کن.</p><button class="btn" onclick="exportBackup()">دانلود پشتیبان</button></article><article class="settings-card"><div class="settings-icon">↥</div><h3>بازیابی اطلاعات</h3><p>یک فایل JSON قبلی را اعتبارسنجی و پس از تأیید جایگزین کن.</p><button class="btn soft" onclick="$('backupInput').click()">انتخاب فایل پشتیبان</button></article><article class="settings-card"><div class="settings-icon">⌘</div><h3>دانلود HTML مستقل</h3><p>دریافت همین برنامه به‌صورت یک فایل HTML با کدهای داخلی؛ اجرای آن به Arena وابسته نیست.</p><button class="btn" onclick="downloadStandalone()">⬇ دانلود فایل HTML مستقل</button></article><article class="settings-card"><div class="settings-icon">▤</div><h3>گزارش ماه جاری</h3><p>خروجی CSV برای بازکردن در صفحه‌گسترده و نگهداری گزارش حساب‌دار.</p><button class="btn soft" onclick="downloadMonthCSV('${reportMonth}',null)">دانلود گزارش CSV</button></article><article class="settings-card"><div class="settings-icon">⇄</div><h3>تنظیمات سرور</h3><p>نسخه فعلی محلی است. برای اشتراک امن میان چند دستگاه، بک‌اند، پایگاه داده، HTTPS و حساب‌های کاربری باید راه‌اندازی شوند.</p><label class="field"><span>نشانی پایه API</span><input id="apiBase" value="${esc(db.settings?.apiBase||'')}" placeholder="https://api.example.com"></label><label class="field"><span>کلید دسترسی سرور (فقط در این نشست)</span><input id="apiToken" type="password" autocomplete="off" placeholder="کلید API که مدیر سرور داده است"></label><div class="form-actions"><button class="btn soft" onclick="saveApiBase()">ذخیره نشانی</button><button class="btn soft" onclick="checkApi()">آزمایش /health</button><button class="btn" onclick="enableServerSync()">اتصال و بارگذاری اولیه</button><button class="btn" onclick="pushToServer(true)">ذخیره اطلاعات روی سرور</button><button class="btn soft" onclick="loadFromServer()">دریافت اطلاعات از سرور</button></div><div id="apiStatus" class="muted" style="font-size:10px;margin-top:8px">${db.settings?.apiBase?'نشانی ذخیره شده؛ اتصال هنوز بررسی نشده.':'سروری تنظیم نشده است.'}</div><div class="notice warn">این بک‌اند اولیه از یک کلید مشترک برای همگام‌سازی استفاده می‌کند و برای بهره‌برداری مالی چندکاربره، قبل از استفاده واقعی باید ورود مستقل نقش‌ها، ممیزی تغییرات و کنترل تعارض چنددستگاهی تکمیل شوند.</div></article><article class="settings-card"><div class="settings-icon">↻</div><h3>شروع دوباره نسخه نمایشی</h3><p>اطلاعات فعلی را با داده‌های آزمایشی پیش‌فرض جایگزین می‌کند. ابتدا نسخه پشتیبان بگیر.</p><button class="btn danger" onclick="resetDemo()">بازنشانی داده‌های نمونه</button></article></div><div class="panel" style="margin-top:14px">${panelHead('راهنمای استفاده واقعی')}<ol style="font-size:11px;line-height:2.3;padding-right:19px;margin:0"><li>نام محصولات، درجه، قیمت تولید و قیمت فروش را با اطلاعات واقعی تطبیق بده.</li><li>فروشگاه‌ها را ثبت کن و تعداد موجودی اولیه یا حواله‌های تحویل را وارد کن.</li><li>در هر فاکتور ریز کالاها و روش پرداخت را ثبت کن.</li><li>گزارش مستقل کارت‌خوان را وارد کن؛ مبلغ داخل فاکتور به‌تنهایی مدرک پرداخت واقعی نیست.</li><li>برای اشتراک اطلاعات از چند دستگاه باید سرور و پایگاه داده واقعی نصب و پیکربندی شود.</li></ol></div>`}
function render(){if(!db.stores.some(s=>s.id===countStore))countStore=db.stores[0]?.id||'';if(reportStore!=='all'&&!db.stores.some(s=>s.id===reportStore))reportStore='all';nav();const pages={dashboard,products:productsPage,stores:storesPage,deliveries:deliveryPage,sales:salesPage,pos:posPage,reconcile:reconcilePage,reports:reportsPage,settings:settingsPage};$('content').innerHTML=(pages[page]||dashboard)();if(page==='sales'){updateSaleTotal();togglePayment()}if(page==='settings'&&$('apiToken'))$('apiToken').value=sessionStorage.getItem(KEY+'-token')||''}
function editProduct(id,key,value){const p=product(id);if(!p)return;if(key==='name'){if(!String(value).trim())return notify('نام محصول نمی‌تواند خالی باشد.');p[key]=String(value).trim()}else if(key==='grade')p[key]=Math.max(1,Math.min(3,num(value)));else if(key==='prod'||key==='price'){if(num(value)<0)return notify('قیمت نمی‌تواند منفی باشد.');p[key]=num(value)}save();notify('تغییر محصول ذخیره شد.');if(key==='name'||key==='grade')render()}
function toggleProduct(id){const p=product(id);if(!p)return;p.active=p.active===false;save();render();notify(p.active?'محصول فعال شد.':'محصول غیرفعال شد؛ سوابق قبلی حفظ شدند.')}
function toggleStore(id){const s=store(id);if(!s)return;s.active=s.active===false;save();render();notify(s.active?'فروشگاه فعال شد.':'فروشگاه غیرفعال شد.')}
function showStoreReport(id){reportStore=id;go('reports')}
function addSaleLine(){const w=$('saleLines');if(!w)return;w.insertAdjacentHTML('beforeend',saleLine(w.querySelectorAll('.sale-line').length));updateSaleTotal()}
function removeSaleLine(btn){const w=$('saleLines');if(w.querySelectorAll('.sale-line').length<=1)return notify('فاکتور باید دست‌کم یک ردیف کالا داشته باشد.');btn.closest('.sale-line').remove();[...w.querySelectorAll('.sale-line')].forEach((e,i)=>e.querySelector('.sale-line-top span').textContent='ردیف '+fa(i+1));updateSaleTotal()}
function saleProductChanged(sel){const p=product(sel.value);if(p)sel.closest('.sale-line').querySelector('[name="price"]').value=p.price;updateSaleTotal()}
function saleLinesData(){return [...document.querySelectorAll('#saleLines .sale-line')].map(l=>({productId:l.querySelector('[name="productId"]').value,qty:num(l.querySelector('[name="qty"]').value),price:num(l.querySelector('[name="price"]').value)}))}
function updateSaleTotal(){const w=$('saleLines');if(!w)return;let total=0;[...w.querySelectorAll('.sale-line')].forEach((l,i)=>{const q=num(l.querySelector('[name="qty"]').value),p=num(l.querySelector('[name="price"]').value),v=q*p;total+=v;l.querySelector('.sale-line-top span').textContent='ردیف '+fa(i+1);l.querySelector('.line-total span').textContent=money(v)});$('saleTotal').textContent=money(total);const method=$('payMethod')?.value,card=$('cardAmount');if(method==='card'&&card)card.value=String(Math.round(total));updatePaymentHint();return total}
function togglePayment(){const method=$('payMethod')?.value,field=$('cardField');if(!method||!field)return;field.classList.toggle('hidden',method==='cash'||method==='other');const card=$('cardAmount');if(method==='card'&&card)card.value=String(Math.round(updateSaleTotal()));if(method==='cash'||method==='other'){if(card)card.value='0'}updatePaymentHint()}
function updatePaymentHint(){const form=$('saleForm');if(!form)return;const method=$('payMethod').value,total=saleLinesData().reduce((a,i)=>a+i.qty*i.price,0),card=num($('cardAmount').value);const h=$('paymentHint');if(method==='card'){h.textContent='بعد از تأیید پرداخت موفق، شماره مرجع رسید را در همین فاکتور وارد کن.';h.className='notice'}else if(method==='mixed'){h.textContent='باقی‌مانده غیرکارت: '+money(Math.max(0,total-card))+'. مبلغ کارت نباید از جمع فاکتور بیشتر باشد.';h.className=card>total?'notice warn':'notice'}else{h.className='notice';h.textContent='این فاکتور بدون مبلغ کارت‌خوان ثبت می‌شود؛ تراکنش مستقل هم نباید برای آن ساخته شود.'}}
$('content').addEventListener('submit',e=>{e.preventDefault();const f=e.target;
 if(f.id==='productForm'){const fd=new FormData(f),name=String(fd.get('name')||'').trim();if(!name)return notify('نام محصول را وارد کن.');db.products.push({id:uid('p'),name,grade:num(fd.get('grade'))||1,unit:String(fd.get('unit')||'عدد'),prod:num(fd.get('prod')),price:num(fd.get('price')),active:true});save();render();notify('محصول جدید ثبت شد.');}
 if(f.id==='storeForm'){const fd=new FormData(f),name=String(fd.get('name')||'').trim();if(!name)return notify('نام فروشگاه را وارد کن.');db.stores.push({id:uid('s'),name,manager:String(fd.get('manager')||'').trim(),phone:String(fd.get('phone')||'').trim(),active:fd.get('active')==='true'});save();render();notify('فروشگاه ثبت شد.');}
 if(f.id==='adjustmentForm'){const fd=new FormData(f),qty=num(fd.get('qty')),sid=String(fd.get('storeId')),pid=String(fd.get('productId')),note=String(fd.get('note')||'').trim();if(!store(sid)||!product(pid)||qty===0||!note)return notify('فروشگاه، محصول، مقدار غیرصفر و شرح مستند لازم است.');db.adjustments.push({id:uid('adj'),storeId:sid,productId:pid,qty,date:String(fd.get('date')),reason:String(fd.get('reason')),note});save();render();notify('اصلاح موجودی با سابقه ثبت شد.');}
 if(f.id==='deliveryForm'){const fd=new FormData(f),qty=num(fd.get('qty'));if(!store(fd.get('storeId'))||!product(fd.get('productId'))||qty<=0)return notify('فروشگاه، محصول و تعداد را بررسی کن.');db.deliveries.push({id:uid('d'),storeId:String(fd.get('storeId')),productId:String(fd.get('productId')),qty,date:String(fd.get('date')),doc:String(fd.get('doc')||'').trim(),note:String(fd.get('note')||'').trim()});save();render();notify('رسید تحویل ثبت شد.');}
 if(f.id==='saleForm'){const fd=new FormData(f),items=saleLinesData().filter(i=>i.qty>0);if(!items.length||items.some(i=>!product(i.productId)||i.price<0||i.qty<=0))return notify('کالا، تعداد و قیمت را بررسی کن.');const sid=String(fd.get('storeId')),required={};items.forEach(i=>required[i.productId]=(required[i.productId]||0)+i.qty);for(const [pid,q] of Object.entries(required)){if(stock(pid,sid)<q)return notify('موجودی دفتری «'+(product(pid)?.name||'کالا')+'» کافی نیست؛ تحویل یا موجودی اول دوره را بررسی کن.')}const total=items.reduce((a,i)=>a+i.qty*i.price,0),method=String(fd.get('method')),card=method==='card'?total:(method==='mixed'?num(fd.get('cardAmount')):0);if(card>total||card<0)return notify('مبلغ کارت‌خوان باید بین صفر و جمع فاکتور باشد.');const ref=String(fd.get('reference')||'').trim();if(ref&&db.sales.some(s=>s.reference===ref))return notify('این شماره مرجع قبلاً در فاکتور دیگری ثبت شده است.');const invoice=String(fd.get('invoice')||'').trim();if(invoice&&db.sales.some(s=>s.invoice===invoice&&s.storeId===sid))return notify('این شماره فاکتور برای این فروشگاه قبلاً استفاده شده است.');db.sales.push({id:uid('sale'),date:String(fd.get('date')),invoice,storeId:sid,items:items.map(i=>({...i})),total,method,cardAmount:card,cashAmount:total-card,reference:ref,note:String(fd.get('note')||'').trim()});save();render();notify('فاکتور ثبت شد؛ برای تطبیق مستقل، گزارش کارت‌خوان را هم وارد کن.');}
 if(f.id==='posForm'){const fd=new FormData(f),date=String(fd.get('date')),amount=num(fd.get('amount')),reference=String(fd.get('reference')||'').trim(),sid=String(fd.get('storeId'));if(!store(sid)||!date||amount<=0||!reference)return notify('فروشگاه، تاریخ، مبلغ و شماره مرجع لازم‌اند.');if(db.pos.some(t=>t.date===date&&t.reference===reference))return notify('این شماره مرجع برای این تاریخ قبلاً وارد شده است.');db.pos.push({id:uid('pos'),storeId:sid,date,amount,reference,terminal:String(fd.get('terminal')||'').trim(),note:String(fd.get('note')||'').trim()});save();render();notify('تراکنش مستقل ثبت شد.');}
});
function saveClosing(){const month=reportMonth,sid=countStore||db.stores[0]?.id;if(!sid)return notify('ابتدا یک فروشگاه بساز.');const inputs=[...document.querySelectorAll('.actual-count')];if(inputs.some(i=>i.value===''))return notify('شمارش واقعی همه محصولات را وارد کن.');const b=monthBounds(month),counts=inputs.map(i=>{const p=product(i.dataset.product);const opening=stock(p.id,sid,b.start),received=delivered(p.id,sid,b.end)-delivered(p.id,sid,b.start),sold=soldQty(p.id,sid,b.start,b.end),adj=adjustments(p.id,sid,b.start,b.end);return {productId:p.id,actual:num(i.value),expected:opening+received-sold+adj}});if(counts.some(c=>c.actual<0))return notify('شمارش واقعی نمی‌تواند منفی باشد.');const varianceCount=counts.filter(c=>Math.abs(c.actual-c.expected)>.0001).length;const obj={month,storeId:sid,closedAt:isoToday(),counts,varianceCount,salesTotal:salesAmount(b.start,b.end,sid),cardTotal:cardFromSales(b.start,b.end,sid),posTotal:posAmount(b.start,b.end,sid)};const idx=db.closings.findIndex(c=>c.month===month&&c.storeId===sid);if(idx>=0)db.closings[idx]=obj;else db.closings.push(obj);save();render();notify('شمارش این دوره ثبت شد؛ اختلاف‌ها برای بررسی نگهداری شدند.')}
function deletePOS(id){if(!confirm('این تراکنش واردشده حذف شود؟ سوابق حذف‌شده قابل تطبیق نخواهند بود.'))return;db.pos=db.pos.filter(t=>t.id!==id);save();render();notify('تراکنش حذف شد.')}
function csvCell(v){return '"'+String(v??'').replace(/"/g,'""')+'"'}
function downloadBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500)}
function exportBackup(){downloadBlob(new Blob([JSON.stringify(db,null,2)],{type:'application/json;charset=utf-8'}),'fadak-backup-'+isoToday()+'.json');notify('فایل پشتیبان آماده شد.')}
$('backupInput').addEventListener('change',e=>{const file=e.target.files?.[0];if(!file)return;const r=new FileReader();r.onload=()=>{try{const x=JSON.parse(r.result);if(!validDb(x))throw new Error('ساختار اطلاعات معتبر نیست.');if(!confirm('تمام اطلاعات مرورگر با فایل انتخاب‌شده جایگزین شود؟ ابتدا اگر لازم است پشتیبان بگیر.'))return;db={...fresh(),...x};save();go('dashboard');notify('اطلاعات بازیابی شد.')}catch(err){alert('بازیابی انجام نشد: '+err.message)}finally{$('backupInput').value=''}};r.readAsText(file)});
function parseCsvLine(line){const out=[];let v='',quoted=false;for(let i=0;i<line.length;i++){const c=line[i];if(c==='"'&&quoted&&line[i+1]==='"'){v+='"';i++}else if(c==='"')quoted=!quoted;else if(c===','&&!quoted){out.push(v.trim());v=''}else v+=c}out.push(v.trim());return out}
$('csvInput').addEventListener('change',e=>{const file=e.target.files?.[0];if(!file)return;const r=new FileReader();r.onload=()=>{try{const rows=String(r.result).replace(/^\uFEFF/,'').split(/\r?\n/).filter(x=>x.trim());if(rows.length<2)throw new Error('فایل سطر داده ندارد.');const head=parseCsvLine(rows[0]).map(x=>x.toLowerCase()),ix=(...keys)=>head.findIndex(h=>keys.includes(h));const di=ix('date','تاریخ','تاریخ تراکنش'),ai=ix('amount','مبلغ','مبلغ (تومان)','amount_rial','مبلغ (ریال)','مبلغ ریالی'),ri=ix('reference','ref','trace','rrn','شماره مرجع','شماره پیگیری'),ti=ix('terminal','پایانه','شماره پایانه'),si=ix('store','فروشگاه','نام فروشگاه');if(ai<0||ri<0)throw new Error('ستون مبلغ و شماره مرجع لازم است.');let added=0,dups=0,skipped=0;for(const row of rows.slice(1)){const a=parseCsvLine(row),raw=Number(String(a[ai]||'').replace(/[٬,\s]/g,''));const rial=['amount_rial','مبلغ (ریال)','مبلغ ریالی'].includes(head[ai]);const amount=rial?raw/10:raw;const reference=a[ri]||'';const date=normDate(di>=0&&a[di]?a[di]:isoToday());let st=null;if(si>=0&&a[si])st=db.stores.find(s=>s.name===a[si]);if(!st)st=db.stores[0];if(!reference||!date||!Number.isFinite(amount)||amount<=0||!st){skipped++;continue}if(db.pos.some(t=>t.date===date&&t.reference===reference)){dups++;continue}db.pos.push({id:uid('pos'),date,amount,reference,terminal:ti>=0?a[ti]||'':'',storeId:st.id,note:'واردشده از CSV'});added++}save();go('pos');notify(`${fa(added)} تراکنش وارد شد؛ تکراری ${fa(dups)}، ردشده ${fa(skipped)}.`)}catch(err){alert('ورود CSV انجام نشد: '+err.message)}finally{$('csvInput').value=''}};r.readAsText(file,'UTF-8')});
function downloadMonthCSV(month,sid){const b=monthBounds(month),storeFilter=sid&&sid!=='null'?sid:null;const rows=[['گزارش','زیتون فدک',monthPersian(month)],['فروشگاه','محصول','درجه','موجودی اول دوره','تحویل ماه','فروش ماه','اصلاحات','موجودی مورد انتظار','ارزش فروش ماه','کارت‌خوان داخل فاکتورها']];for(const s of db.stores.filter(x=>!storeFilter||x.id===storeFilter)){for(const p of db.products){const opening=stock(p.id,s.id,b.start),received=delivered(p.id,s.id,b.end)-delivered(p.id,s.id,b.start),sold=soldQty(p.id,s.id,b.start,b.end),adj=adjustments(p.id,s.id,b.start,b.end),expected=opening+received-sold+adj;const value=sum(db.sales.filter(x=>x.storeId===s.id&&x.date>=b.start&&x.date<b.end),x=>sum(x.items.filter(i=>i.productId===p.id),i=>i.qty*i.price));rows.push([s.name,p.name,p.grade,opening,received,sold,adj,expected,value,cardFromSales(b.start,b.end,s.id)])}}rows.push([],['جمع فروش',salesAmount(b.start,b.end,storeFilter)],['کارت‌خوان ثبت‌شده در فاکتورها',cardFromSales(b.start,b.end,storeFilter)],['تراکنش‌های مستقل واردشده',posAmount(b.start,b.end,storeFilter)],['اختلاف جمع کارت',cardFromSales(b.start,b.end,storeFilter)-posAmount(b.start,b.end,storeFilter)]);downloadBlob(new Blob(['\uFEFF'+rows.map(r=>r.map(csvCell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),'fadak-month-'+month+'.csv');notify('گزارش CSV دانلود شد.')}
function downloadStandalone(){try{const c=document.documentElement.cloneNode(true);['content','sideNav','mobileNav'].forEach(i=>c.querySelector('#'+i).innerHTML='');const tt=c.querySelector('#toast');tt.className='toast hidden';tt.textContent='';const sp=c.querySelector('#splash');if(sp)sp.remove();c.querySelector('#content').className='content';const source='<!doctype html>\n'+c.outerHTML;downloadBlob(new Blob([source],{type:'text/html;charset=utf-8'}),'zeytoon-fadak-standalone.html');notify('فایل HTML مستقل آماده دانلود است.')}catch(e){notify('دانلود مستقیم انجام نشد؛ مرورگر اجازه ساخت فایل را نداد.')}}
function resetDemo(){if(!confirm('اطلاعات فعلی پاک و با داده‌های آزمایشی جایگزین می‌شود. اول پشتیبان بگیری؟'))return;db=fresh();save();reportMonth=isoToday().slice(0,7);countStore=db.stores[0]?.id||'';go('dashboard');notify('داده‌های نمونه بازنشانی شدند.')}
function saveApiBase(){const v=$('apiBase').value.trim();if(v&&!/^https?:\/\//i.test(v))return notify('نشانی باید با https:// یا http:// شروع شود.');db.settings=db.settings||{};db.settings.apiBase=v;save();$('apiStatus').textContent=v?'نشانی ذخیره شد؛ اتصال هنوز آزمایش نشده.':'نشانی سرور پاک شد.';notify('تنظیم سرور ذخیره شد؛ اتصال آنلاین ایجاد نشده است.')}
async function checkApi(){if(window.FADAK_DEMO===true){const status=$('apiStatus');if(status)status.textContent='نسخه‌ی نمایشی است؛ اتصال به سرور در این نسخه فعال نیست.';return notify('این نسخه فقط برای نمایش است؛ داده‌ها ساختگی و محلی هستند.')}const base=($('apiBase')?.value||db.settings?.apiBase||'').trim().replace(/\/$/,'');if(!base)return notify('ابتدا نشانی API را وارد کن.');const status=$('apiStatus');if(status)status.textContent='در حال بررسی واقعی /health…';try{const r=await fetch(base+'/health',{method:'GET',headers:{'Accept':'application/json'}});if(!r.ok)throw new Error('HTTP '+r.status);const data=await r.json();if(status)status.textContent='پاسخ واقعی سرور: '+JSON.stringify(data).slice(0,220);notify('سرور به درخواست /health پاسخ داد.')}catch(e){if(status)status.textContent='اتصال تأیید نشد: '+e.message+'؛ آدرس، HTTPS و CORS را بررسی کن.';notify('اتصال سرور تأیید نشد؛ اطلاعات محلی دست‌نخورده ماند.')}}
function apiConfig(){if(window.FADAK_DEMO===true)throw new Error('این نسخه فقط برای نمایش است؛ اتصال به سرور در آن غیرفعال است.');const base=String($('apiBase')?.value||db.settings?.apiBase||'').trim().replace(/\/$/,'');const token=String($('apiToken')?.value||sessionStorage.getItem(KEY+'-token')||'').trim();if(!base)throw new Error('ابتدا نشانی API را تنظیم کن.');if(!token)throw new Error('کلید دسترسی سرور را وارد کن.');return {base,token}}
function saveApiToken(){try{const {token}=apiConfig();sessionStorage.setItem(KEY+'-token',token);notify('کلید فقط تا پایان این نشست نگهداری می‌شود.');}catch(e){notify(e.message)}}
async function enableServerSync(){try{const {base,token}=apiConfig();db.settings=db.settings||{};db.settings.apiBase=base;save();sessionStorage.setItem(KEY+'-token',token);const h=await fetch(base+'/health',{headers:{'Accept':'application/json'}});if(!h.ok)throw new Error('Health check: HTTP '+h.status);const r=await fetch(base+'/api/state',{headers:{'Accept':'application/json','Authorization':'Bearer '+token}});if(!r.ok)throw new Error('دریافت وضعیت: HTTP '+r.status);const payload=await r.json();sessionStorage.setItem(KEY+'-version',String(payload.version||0));if(payload.state){if(confirm('اطلاعات موجود در سرور جایگزین اطلاعات این دستگاه شود؟ لغو یعنی اطلاعات فعلی روی سرور بارگذاری می‌شود.')){if(!validDb(payload.state))throw new Error('ساختار داده‌های سرور معتبر نیست.');db={...fresh(),...payload.state};localStorage.setItem(KEY,JSON.stringify(db));sessionStorage.setItem(KEY+'-sync','1');render();notify('اطلاعات از سرور بارگذاری و همگام‌سازی نشست فعال شد.')}else{sessionStorage.setItem(KEY+'-sync','1');const ok=await pushToServer(false);if(!ok)throw new Error('ذخیره اطلاعات این دستگاه روی سرور تأیید نشد. وضعیت اتصال و نسخه داده را بررسی کن.');notify('اطلاعات این دستگاه روی سرور ذخیره شد و همگام‌سازی نشست فعال است.')}}else{sessionStorage.setItem(KEY+'-sync','1');const ok=await pushToServer(false);if(!ok)throw new Error('ذخیره اولیه روی سرور تأیید نشد.');notify('فضای سرور آماده شد و داده‌های این دستگاه بارگذاری شدند.')}const st=$('apiStatus');if(st)st.textContent='همگام‌سازی فعال است تا پایان این نشست؛ قبل از تغییرات عمده از اطلاعات پشتیبان بگیر.'}catch(e){const st=$('apiStatus');if(st)st.textContent='اتصال/همگام‌سازی انجام نشد: '+e.message;notify('اتصال برقرار نشد: '+e.message)}}
let syncTimer=null,syncBusy=false;
function queueServerSync(){clearTimeout(syncTimer);syncTimer=setTimeout(()=>pushToServer(false),900)}
async function pushToServer(show=true){try{const {base,token}=apiConfig();const version=sessionStorage.getItem(KEY+'-version')||'0';const r=await fetch(base+'/api/state',{method:'PUT',headers:{'Authorization':'Bearer '+token,'Content-Type':'application/json','Accept':'application/json','If-Match':version},body:JSON.stringify({state:db})});if(!r.ok){if(r.status===409)throw new Error('داده‌های سرور در دستگاه دیگری تغییر کرده‌اند؛ ابتدا اطلاعات سرور را دوباره دریافت کن تا تغییرات قبلی بازنویسی نشوند.');throw new Error('HTTP '+r.status)}const out=await r.json();sessionStorage.setItem(KEY+'-version',String(out.version||0));const st=$('apiStatus');if(st)st.textContent='آخرین ذخیره سرور: '+(out.updatedAt||'تأیید شد')+'.';if(show)notify('اطلاعات روی سرور ذخیره شد.');return true}catch(e){const st=$('apiStatus');if(st)st.textContent='همگام‌سازی ناموفق: '+e.message;if(show)notify('ذخیره روی سرور ناموفق بود: '+e.message);return false}}
async function loadFromServer(){try{const {base,token}=apiConfig();const r=await fetch(base+'/api/state',{headers:{'Authorization':'Bearer '+token,'Accept':'application/json'}});if(!r.ok)throw new Error('HTTP '+r.status);const payload=await r.json();sessionStorage.setItem(KEY+'-version',String(payload.version||0));if(!payload.state)throw new Error('هنوز داده‌ای روی سرور نیست. ابتدا اتصال را فعال کن تا اطلاعات بارگذاری شوند.');if(!validDb(payload.state))throw new Error('ساختار داده‌های سرور معتبر نیست.');if(!confirm('اطلاعات محلی با نسخه سرور جایگزین شود؟ ابتدا در صورت نیاز پشتیبان بگیر.'))return;db={...fresh(),...payload.state};localStorage.setItem(KEY,JSON.stringify(db));sessionStorage.setItem(KEY+'-token',token);sessionStorage.setItem(KEY+'-version',String(payload.version||0));sessionStorage.setItem(KEY+'-sync','1');reportStore='all';go('dashboard');notify('اطلاعات سرور بارگذاری شد.')}catch(e){notify('دریافت از سرور انجام نشد: '+e.message)}}
$('themeBtn').addEventListener('click',()=>{theme=theme==='light'?'dark':'light';document.documentElement.dataset.theme=theme;localStorage.setItem(KEY+'-theme',theme);$('themeBtn').textContent=theme==='light'?'◐':'☀'});$('themeBtn').textContent=theme==='light'?'◐':'☀';
